CREATE PROCEDURE VPAYFAX.CREATE_DUMMY_FAX_RECORD (
 INOUT PUSTOKEN CHAR(128) ,
 INOUT PRETCODE CHAR(4) ,
 INOUT PRETDESC CHAR(256) ,
 IN P_CORID CHAR(20) )
 DYNAMIC RESULT SETS 1
 LANGUAGE SQL
 SPECIFIC VPAYFAX.SP_CDFR
 NOT DETERMINISTIC
 MODIFIES SQL DATA
 CALLED ON NULL INPUT
 SET OPTION  ALWBLK = *ALLREAD ,
 ALWCPYDTA = *OPTIMIZE ,
 COMMIT = *NONE ,
 DECRESULT = (31, 31, 00) ,
 DFTRDBCOL = *NONE ,
 DYNDFTCOL = *NO ,
 DYNUSRPRF = *USER ,
 SRTSEQ = *HEX
 BEGIN
DECLARE NEW_FSMJOB_ID INTEGER ;
DECLARE RS_CURSOR CURSOR FOR
SELECT
NEW_FSMJOB_ID AS REC_ID
FROM
SYSIBM . SYSDUMMY1
 ;
INSERT INTO VPAYFAX . FSMJOB ( QUEUE , FAX_STATUS , SE_TX_ID , CORID , CREATE_TS )
SELECT
'MAILFAX' AS QUEUE ,
'MAILEDFAX' AS FAX_STATUS ,
DMTXID AS SE_TX_ID ,
DMRECID AS CORID ,
CURRENT_TIMESTAMP AS CREATE_TS
FROM
SEWCPS . CPSCOR
WHERE
DMRECID = P_CORID
;
VALUES IDENTITY_VAL_LOCAL ( ) INTO NEW_FSMJOB_ID ;

OPEN RS_CURSOR ;
END  ;

