CREATE PROCEDURE VPAYFAX.DROP_FAILED_FAX_2_RETRY ( )
 DYNAMIC RESULT SETS 1
 LANGUAGE SQL
 SPECIFIC VPAYFAX.DROP_FAILED_FAX_2_RETRY
 NOT DETERMINISTIC
 MODIFIES SQL DATA
 CALLED ON NULL INPUT
 SET OPTION  ALWBLK = *ALLREAD ,
 ALWCPYDTA = *OPTIMIZE ,
 COMMIT = *NONE ,
 DECRESULT = (31, 31, 00) ,
 DYNDFTCOL = *NO ,
 DYNUSRPRF = *USER ,
 SRTSEQ = *HEX
 BEGIN
DECLARE ROWSUPPED INTEGER ;
DECLARE C1 CURSOR WITH RETURN TO CLIENT FOR
SELECT ROWSUPPED AS FAXES_DUMPED_BACK_INTO_QUEUE FROM SYSIBM . SYSDUMMY1 ;
UPDATE
VPAYFAX . FSMJOB
SET
QUEUE = 'NORMAL' ,
FAX_STATUS = 'DUPENUMBER' ,
RETRYCOUNT = 5
WHERE
CREATE_TS >= CURRENT_DATE
AND RESERVE_NAME = 'MEDICAL'
AND FAX_STATUS = 'RTEXCEEDED'
;
GET DIAGNOSTICS ROWSUPPED = ROW_COUNT ;
OPEN C1 ;
END  ;

