SET TOKTRIM = TRIM ( PUSTOKEN ) ;
SET USERID = THEUSER ;
IF THEUSER = '' THEN
CALL VPAYSEC / SP_VERIFY_TOKEN ( TOKTRIM , USERID , PRETCODE , PRETDESC ) ;
ELSE
SELECT '0000' INTO PRETCODE FROM VPAYSEC / RPORTSEC WHERE TOKENGUID = TOKTRIM AND USRNAME = USERID AND TIMEOUT > CURRENT_TIMESTAMP ;
END IF ;

IF PRETCODE = '0000' THEN
SET RESULTQRY = '    SELECT DISTINCT        TMF.TMCLIC,        TMF.TMBILC,
      TMF.TMBILT,        TMF.TMTXID AS TRAN_ID,        TMF.TMUDSP1 AS OLD_TRAN_ID,        TMF.TMPAYEN,        F_GET_CTRSTAT(TMF.TMCLIC,TMF.TMTXID) AS PAY_ST
ATUS,        FJ.FAX_STATUS,        COR.DMRCVPOC AS CONTACT_NAME,        COR.DMRCVPHN AS VOICE_NUM,        FJ.FAXNUMBER AS FAX_NUMBER,        FJ.ID AS FAX_J
OB_ID,        F_TRAN_LOAD_DATE(TMF.TMTXID) AS LOAD_DATE,        TMF.TMLDAM AS LOAD_AMOUNT,        TMF.TMCVAL AS CURRENT_AMOUNT,        TMF.TMAVAL AS AVAILAB
LE_AMOUNT    FROM         VPAYFAX / FSMJOB AS FJ         JOIN SEWCPS / CPSCOR AS COR ON ( FJ . CORRESP_ID = COR . DMRECID )         JOIN SEWCPS / CPSTMF AS
TMF ON ( FJ . SE_TX_ID = TMF . TMTXID AND COR . DMTXID = TMF . TMTXID )
 JOIN SEWCPS / CPSCTR AS CTR ON ( FJ . SE_TX_ID = CTR . CTRLTRN )        JOIN VPAYSEC / SECTBP AS TBP ON ( TMF.TMCLIC = TBP.OBJECT_TPA
               AND TMF.TMBILC = TBP.OBJECT_BE
     AND TMF.TMBILT = TBP.OBJECT_TP)    
     WHERE         FAX_STATUS IN (''CANCELLED'',''BADNUMBER'',''RTEXCEEDED'',''FAILED'')      AND        FJ.CREATE_TS >=
'''
DATE
'''    ' ;

SET EXTRA_WHERE = '' ;

IF ( TRANSTAT != '' ) THEN
SET EXTRA_WHERE = EXTRA_WHERE
END IF ;

IF ( BILT != '' ) THEN
SET EXTRA_WHERE = EXTRA_WHERE
END IF ;

IF ( BILC != '' ) THEN
SET EXTRA_WHERE = EXTRA_WHERE
END IF ;

IF ( CLIC != '' ) THEN
SET EXTRA_WHERE = EXTRA_WHERE
END IF ;

IF ( EXCLUDE_SUCCESS = 'on' ) THEN
SET EXTRA_WHERE = EXTRA_WHERE
_ID FROM FSMJOB WHERE FAX_STATUS = ''SENT'')  ;
END IF ;

IF ( FAX_STATUS != '' ) THEN
SET EXTRA_WHERE = EXTRA_WHERE
' ;
END IF ;

SET RESULTQRY = TRIM ( RESULTQRY )
'
PREPARE DYNAMIC_QUERY FROM RESULTQRY ;
OPEN RS_CURSOR ;
END IF ;
END  ;

