CREATE PROCEDURE VPAYFAX.GET_FAX_JOBS_BY_PHONE_NUMBER (
 INOUT PUSTOKEN CHAR(128) ,
 INOUT PRETCODE CHAR(4) ,
 INOUT PRETDESC CHAR(256) ,
 IN PFAXNUM CHAR(20) )
 DYNAMIC RESULT SETS 1
 LANGUAGE SQL
 SPECIFIC VPAYFAX.GFJBPN
 NOT DETERMINISTIC
 MODIFIES SQL DATA
 CALLED ON NULL INPUT
 SET OPTION  ALWBLK = *ALLREAD ,
 ALWCPYDTA = *OPTIMIZE ,
 COMMIT = *NONE ,
 DECRESULT = (31, 31, 00) ,
 DFTRDBCOL = *NONE ,
 DYNDFTCOL = *NO ,
 DYNUSRPRF = *USER ,
 SRTSEQ = *HEX
 BEGIN
DECLARE TOKTRIM VARCHAR ( 128 ) ;
DECLARE USERID CHAR ( 20 ) ;
DECLARE PN VARCHAR ( 20 ) ;
DECLARE PN1 VARCHAR ( 20 ) ;
DECLARE RESULTQRY VARCHAR ( 10000 ) ;
DECLARE EXTRA_WHERE VARCHAR ( 10000 ) ;
DECLARE RS_CURSOR CURSOR FOR
SELECT
FJ . ID AS FAX_JOB ,
FJ . SE_TX_ID AS SE_TX_ID ,
COALESCE ( COR . DMRECID , 0 ) AS CORRESPONDENCE_ID ,
COALESCE ( COR . DMCLIC , '' ) AS CLIC ,
COALESCE ( TMF . TMUDSP1 , '' ) AS USERDISPLAY1 ,
COALESCE ( COR . DMRCVNM , '' ) AS RECIPIENT_NAME ,
FJ . FAXNUMBER
FROM
VPAYFAX / FSMJOB AS FJ
LEFT JOIN SEWCPS / CPSCOR AS COR ON ( FJ . CORRESP_ID = COR . DMRECID )
LEFT JOIN SEWCPS / CPSTMF AS TMF ON ( FJ . SE_TX_ID = TMF . TMTXID AND COR . DMTXID = TMF . TMTXID )
WHERE
FJ . FAXNUMBER LIKE PN
OR
FJ . FAXNUMBER LIKE PN1
ORDER BY
FJ . CREATE_TS DESC , LAST_STATUS_TS DESC
;



SET TOKTRIM = TRIM ( PUSTOKEN ) ;
SET USERID = '' ;
CALL VPAYSEC / SP_VERIFY_TOKEN ( TOKTRIM , USERID , PRETCODE , PRETDESC ) ;
IF PRETCODE = '0000' THEN
SET PN = TRIM ( PFAXNUM )
SET PN1 = '1'


OPEN RS_CURSOR ;
END IF ;
END  ;

