CREATE PROCEDURE VPAYFAX.SLA1HR (
 IN IN_FAXNO CHAR(10) ,
 IN IN_JIRA VARCHAR(10) DEFAULT  'SLA1HR'  )
 LANGUAGE SQL
 SPECIFIC VPAYFAX.SLA1HR
 NOT DETERMINISTIC
 MODIFIES SQL DATA
 CALLED ON NULL INPUT
 SET OPTION  ALWBLK = *ALLREAD ,
 ALWCPYDTA = *OPTIMIZE ,
 COMMIT = *NONE ,
 DECRESULT = (31, 31, 00) ,
 DLYPRP = *NO ,
 DYNDFTCOL = *NO ,
 DYNUSRPRF = *USER ,
 SRTSEQ = *HEX
 BEGIN
DECLARE STMT VARCHAR ( 2000 ) ;
DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
SET STMT = '
                                            INSERT INTO VPAYBRDDTA.OVLARC

                (provider_taxid,
                                                         format_postal_code,

                 provider_name,
                                                         provider_first_name,

                 provider_last_name,
                                                         provider_common_name,

                 provider_address_line_1,
                                                         provider_address_line_2,
                 provider_address_line_3,
                                                         provider_city,

                 provider_state_province,
                                                         provider_county,

                 provider_country,
                                                         provider_postal_code,

                 provider_voice,
                                                         provider_fax,

                 format_zip5,
                                                         format_zip9,

                 format_zipl4,
                                                         pvdmast_updated_date,

                 confidence_level,
                                                         collection_set,

                 collection_date,
                                                         created_timestamp,

                 created_by_program,
                                                         created_by_user,

                 changed_timestamp,
                                                         changed_by_program,

                 changed_by_user,
                                                         arc_created_timestamp,

                 arc_created_by_program,
                                                         arc_created_by_user)

    SELECT provider_taxid,
                                                   format_postal_code,

           provider_name,
                                                   provider_first_name,

           provider_last_name,
                                                   provider_common_name,

           provider_address_line_1,
                                                   provider_address_line_2,

           provider_address_line_3,
                                                   provider_city,

           provider_state_province,
                                                   provider_county,

           provider_country,
                                                   provider_postal_code,

           provider_voice,
                                                   provider_fax,

           format_zip5,
                                                   format_zip9,

           format_zipl4,
                                                   pvdmast_updated_date,

           confidence_level,
                                                   collection_set,

           collection_date,
                                                   created_timestamp,

           created_by_program,
                                                   created_by_user,

           changed_timestamp,
                                                   changed_by_program,

           changed_by_user,
                                                   CURRENT_TIMESTAMP --arc_created_timestamp
           ,
                                                   ''SQL-Per TK'' --arc_created_by_program
           ,
                                                   user --arc_created_by_user

    FROM   OUTVNDLU
                                            WHERE  provider_fax = ?

  ' ;
PREPARE STMT_OVLARC FROM STMT ;
EXECUTE STMT_OVLARC USING IN_FAXNO ;
---------------------------------------------------------------------------------------------
-- 4. Edit current OVL
---------------------------------------------------------------------------------------------
SET STMT = '
                                            update VPAYBRDDTA.OUTVNDLU

    set
                                                provider_fax = '''',

        changed_timestamp = current_timestamp,
                                                changed_by_program = ?,

        changed_by_user = user
                                            where

        provider_fax = ?
                                          ' ;
PREPARE UP_OVL FROM STMT ;
EXECUTE UP_OVL USING IN_JIRA , IN_FAXNO ;
---------------------------------------------------------------------------------------------
-- 5. Remove bad phone from providers
---------------------------------------------------------------------------------------------
SET STMT = '
                                            Update VPAYBRDDTA.pvdphon

    set
                                                 number = '''',

         changed_timestamp = current_timestamp,
                                                 changed_by_program = ?,

         changed_by_user = user
                                            WHERE

          number = ? and
                                                  provider_phone_type_id = 3

  ' ;
PREPARE EXP_PVD FROM STMT ;
EXECUTE EXP_PVD USING IN_JIRA , IN_FAXNO ;
---------------------------------------------------------------------------------------------
-- 6. Expire + Replace bad Pref
---------------------------------------------------------------------------------------------
SET STMT = '
                                            UPDATE VPAYBRDDTA.PVDPREF

    SET    active_to_date = current_date -1 day,
                                                   changed_timestamp = CURRENT_TIMESTAMP,
           changed_by_user = user,
                                                   changed_by_program = ?

    WHERE  fax = ?
                                          ' ;
PREPARE EXP_TPA FROM STMT ;
EXECUTE EXP_TPA USING IN_JIRA , IN_FAXNO ;
SET STMT = '
                                            INSERT INTO VPAYBRDDTA.pvdpref

    (
                                              origin,

      tpa,
                                              taxid,

      format_zip5,
                                              format_zip9,

      payment_type_code,
                                              sending_instructions,

      voice,
                                              fax,

      ceiling_amount,
                                              active_from_date,

      active_to_date,
                                              created_timestamp,

      created_by_user,
                                              created_by_program

    )
                                              SELECT

        origin,
                                                tpa,

        taxid,
                                                format_zip5,

        format_zip9,
                                                payment_type_code,

        sending_instructions,
                                                voice,

        '''',
                                                ceiling_amount,

        current_date - 1 day,
                                                ''9999-12-31'',

        current_timestamp,
                                                user,

        ?
                                              FROM

        PVDPREF
                                              WHERE

        changed_by_user = user and
                                                changed_by_program = ?

  ' ;
PREPARE REP_TPA FROM STMT ;
EXECUTE REP_TPA USING IN_JIRA , IN_JIRA ;
---------------------------------------------------------------------------------------------
-- 7. Edit NFPYDT TXns not yet loaded
---------------------------------------------------------------------------------------------
SET STMT = '
                                            UPDATE VPAYBRDDTA.NFPYDT

    SET
                                                use_fax_number = '''',

        sending_instructions = ''Z'' ,
                                                changed_by_program = ?,

        changed_by_user = USER
                                            where

        use_fax_number = ? AND
                                                sending_instructions = ''F'' AND        load_status <> ''L''
                                                     ' ;
PREPARE UP_NFP FROM STMT ;
EXECUTE UP_NFP USING IN_JIRA , IN_FAXNO ;
---------------------------------------------------------------------------------------------
-- 8. Kill running faxes - send message to Fax Distro System
---------------------------------------------------------------------------------------------
CALL VPAYPGM . SP_KILLFAX ( IN_FAXNO ) ;
---------------------------------------------------------------------------------------------
-- 9. Kill runinng faxes
--   *!*NOTE*!*
---  FSMJOB uses 11 digit phone numbers. Make sure the Fax Number has the 1 in f--ront.
---------------------------------------------------------------------------------------------
SET STMT = '
                                            UPDATE VPAYFAX.FSMJOB

    SET
                                                FAX_STATUS = ''KILLED'',

        QUEUE = ?
                                            WHERE

        FAXNUMBER =''1''
                                                fax_status NOT in ( ''SENT'')

  ' ;
PREPARE KILL_FAX FROM STMT ;
EXECUTE KILL_FAX USING IN_JIRA , IN_FAXNO ;
END  ;

