CREATE PROCEDURE VPAYFAX.SP_CANCEL_FAX_JOB (
 INOUT PUSTOKEN CHAR(128) ,
 INOUT PRETCODE CHAR(4) ,
 INOUT PRETDESC CHAR(256) ,
 IN PJOBNUM INTEGER )
 LANGUAGE SQL
 SPECIFIC VPAYFAX.SPCANFJ
 NOT DETERMINISTIC
 MODIFIES SQL DATA
 CALLED ON NULL INPUT
 SET OPTION  ALWBLK = *ALLREAD ,
 ALWCPYDTA = *OPTIMIZE ,
 COMMIT = *NONE ,
 DECRESULT = (31, 31, 00) ,
 DFTRDBCOL = *NONE ,
 DLYPRP = *NO ,
 DYNDFTCOL = *NO ,
 DYNUSRPRF = *USER ,
 SRTSEQ = *HEX
 BEGIN
DECLARE TOKTRIM VARCHAR ( 128 ) ;
DECLARE USERID CHAR ( 20 ) ;
DECLARE REC_COUNT INTEGER ;
DECLARE BILC CHAR ( 20 ) ;
DECLARE CLIENT CHAR ( 10 ) ;
DECLARE OBJECT CHAR ( 512 ) ;
DECLARE ACTION CHAR ( 10 ) ;
DECLARE CORRESP_ID INTEGER ;
DECLARE QUEUE CHAR ( 10 ) ;
SET TOKTRIM = TRIM ( PUSTOKEN ) ,
USERID = '' ;
 SET CLIENT = 'NOTFOUND' ;
CALL VPAYSEC . SP_VERIFY_TOKEN ( TOKTRIM , USERID , PRETCODE , PRETDESC ) ;
IF PRETCODE = '0000' THEN
SELECT T . TMCLIC , T . TMBILC , F . CORRESP_ID , F . QUEUE INTO CLIENT , BILC , CORRESP_ID , QUEUE
FROM FSMJOB F JOIN SEWCPS . CPSTMF T ON F . SE_TX_ID = T . TMTXID
WHERE ID = PJOBNUM
AND FAX_STATUS IN ( 'HOLD' )
;
IF QUEUE = 'FAXDISTRO' THEN
CALL VPAYPGM . SP_CHANGE_FAX_STATUS ( 'CANCEL' , CORRESP_ID ) ;
ELSE
IF CLIENT = 'NOTFOUND' THEN
SET PRETCODE = '0001' ,
PRETDESC = 'Fax job is not able to be cancelled' ;
ELSE
SET OBJECT = 'UNIVERSE
'
ACTION = 'DELETE' ;
CALL VPAYSEC . SP_CHECK_OBJECT_SECURITY (
USERID , OBJECT , ACTION , PRETCODE , PRETDESC ) ;
IF PRETCODE = '0000' THEN
UPDATE FSMJOB
SET FAX_STATUS = 'CANCELLED'
WHERE ID = PJOBNUM ;
UPDATE CPSCOR
SET DMSTAT = 'CANCELLED'
WHERE DMRECID = CORRESP_ID ;
SET PRETDESC = 'Fax job cancelled' ;
END IF ;
END IF ;
END IF ;
END IF ;
END  ;

