CREATE PROCEDURE VPAYFAX.SP_CHANGE_FAX_NUMBER (
 INOUT PUSTOKEN CHAR(128) ,
 INOUT PRETCODE CHAR(4) ,
 INOUT PRETDESC CHAR(256) ,
 IN PJOBNUM INTEGER ,
 IN PFAXNUM CHAR(20) )
 LANGUAGE SQL
 SPECIFIC VPAYFAX.SPCHGFN
 NOT DETERMINISTIC
 MODIFIES SQL DATA
 CALLED ON NULL INPUT
 SET OPTION  ALWBLK = *ALLREAD ,
 ALWCPYDTA = *OPTIMIZE ,
 COMMIT = *NONE ,
 DECRESULT = (31, 31, 00) ,
 DFTRDBCOL = *NONE ,
 DLYPRP = *NO ,
 DYNDFTCOL = *NO ,
 DYNUSRPRF = *USER ,
 SRTSEQ = *HEX
 BEGIN
DECLARE TOKTRIM VARCHAR ( 128 ) ;
DECLARE USERID CHAR ( 20 ) ;
DECLARE REC_COUNT INTEGER ;
DECLARE BILC CHAR ( 20 ) ;
DECLARE CLIENT CHAR ( 10 ) ;
DECLARE OBJECT CHAR ( 512 ) ;
DECLARE ACTION CHAR ( 10 ) ;
DECLARE CORRESP_ID INT ;
DECLARE QUEUE CHAR ( 10 ) ;
SET TOKTRIM = TRIM ( PUSTOKEN ) ,
USERID = '' ,
CLIENT = 'NOTFOUND' ;
CALL VPAYSEC . SP_VERIFY_TOKEN ( TOKTRIM , USERID , PRETCODE , PRETDESC ) ;
IF PRETCODE = '0000' THEN
SELECT T . TMCLIC , T . TMBILC , F . QUEUE , F . CORRESP_ID
INTO CLIENT , BILC , QUEUE , CORRESP_ID
FROM FSMJOB F JOIN SEWCPS . CPSTMF T ON F . SE_TX_ID = T . TMTXID
WHERE ID = PJOBNUM
AND FAX_STATUS IN ( 'HOLD' )
;
IF CLIENT = 'NOTFOUND' THEN
SET PRETCODE = '0001' ,
PRETDESC = 'Fax is not able to be changed' ;
ELSE
SET OBJECT = 'UNIVERSE
'
ACTION = 'DELETE' ;
CALL VPAYSEC . SP_CHECK_OBJECT_SECURITY (
USERID , OBJECT , ACTION , PRETCODE , PRETDESC ) ;

IF PRETCODE = '0000' THEN
IF QUEUE = 'FAXDISTRO' THEN
CALL VPAYPGM . SP_UPDATE_FAX_NUMBER ( PFAXNUM , CORRESP_ID ) ;
ELSE
SELECT COUNT ( * ) INTO REC_COUNT
FROM SEWCPS . CALLCODES
WHERE
CALLCODE = SUBSTR ( PFAXNUM , 1 , 6 )
OR
CALLCODE = SUBSTR ( PFAXNUM , 2 , 6 )
 ;
IF REC_COUNT = 0 THEN
--Need to add the Long Distance 1
UPDATE FSMJOB SET FAXNUMBER = '1'
WHERE ID = PJOBNUM ;
ELSE
--Don't need to add Long Distance 1
UPDATE FSMJOB SET FAXNUMBER = PFAXNUM
WHERE ID = PJOBNUM ;
END IF ;
SET PRETDESC = 'Fax number changed' ;
END IF ;
END IF ;
END IF ;
END IF ;
END  ;

