TO QPGMR WITH GRANT OPTION ;


CREATE PROCEDURE VPAYFAX.SP_CHECK_DROP (
 INOUT PUSTOKEN CHAR(128) ,
 INOUT PRETCODE CHAR(4) ,
 INOUT PRETDESC CHAR(256) ,
 IN PTRANNUM INTEGER )
 LANGUAGE SQL
 SPECIFIC VPAYFAX.SPCHKDRP
 NOT DETERMINISTIC
 MODIFIES SQL DATA
 CALLED ON NULL INPUT
 SET OPTION  ALWBLK = *ALLREAD ,
 ALWCPYDTA = *OPTIMIZE ,
 COMMIT = *NONE ,
 DECRESULT = (31, 31, 00) ,
 DFTRDBCOL = *NONE ,
 DYNDFTCOL = *NO ,
 DYNUSRPRF = *USER ,
 SRTSEQ = *HEX
 BEGIN
DECLARE TOKTRIM VARCHAR ( 128 ) ;
DECLARE USERID CHAR ( 20 ) ;
DECLARE COUNTVAR INTEGER ;
SET COUNTVAR = 0 ;
SET TOKTRIM = TRIM ( PUSTOKEN ) ;

SET USERID = '' ;
CALL VPAYSEC / SP_VERIFY_TOKEN ( TOKTRIM , USERID , PRETCODE , PRETDESC ) ;
IF PRETCODE = '0000' THEN
SELECT COUNT ( * ) INTO COUNTVAR FROM CPSCOR WHERE DMTXID = PTRANNUM AND DMSTAT
IN
(
'DUPENUMBER' ,
'HOLD' ,
'QUEUED' ,
'REQUESTED' ,
'RETRY' ,
'WORKING'
) ;
--Check for incompatible Corresponsence
IF COUNTVAR <> 0 THEN
SET PRETCODE = '9001' ;
SET PRETDESC = 'You have one or more correspondence records in an incompatible state.' ;
ELSE
SELECT COUNT ( * ) INTO COUNTVAR FROM FSMJOB WHERE SE_TX_ID = PTRANNUM AND FAX_STATUS IN
(
'HOLD' ,
'PENDING' ,
'REQUESTED' ,
'DUPENUMBER'
) ;
--Check for incompatible Fax Jobs
IF COUNTVAR <> 0 THEN
SET PRETCODE = '9002' ;
SET PRETDESC = 'You have one or more fax jobs in an incompatible state.' ;
END IF ;
END IF ;
END IF ;
END  ;

