TATUS AND X1 . QUEUE = X . QUEUE )
  ( SELECT COUNT ( * ) FROM VPAYFAX . FSMJOB X1 WHERE X1 . CREATE_TS BETWEEN V_TODAY AND V_TOMMOROW AND X1 . SRVIPADD = X . SRVIPADD AND X1 . FAX_STATUS = X . F
AX_STATUS AND X1 . QUEUE = X . QUEUE )
   --count(*)
 FROM
