  ( SELECT COUNT ( * ) FROM VPAYFAX . FSMJOB X1 WHERE X1 . CREATE_TS BETWEEN V_TS40 AND V_TS40E AND X1 . SRVIPADD = X . SRVIPADD AND X1 . FAX_STATUS = X . FAX_S
