CREATE PROCEDURE VPAYFAX.SP_GET_FAX_STATUS (
 IN PAYLOAD_IN CLOB(165535) ,
 OUT PAYLOAD_OUT CLOB(165535) ,
 OUT PRETCODE CHAR(4) ,
 OUT PRETDESC CHAR(256) )
 LANGUAGE SQL
 SPECIFIC VPAYFAX.SPGETFXSTS
 NOT DETERMINISTIC
 MODIFIES SQL DATA
 CALLED ON NULL INPUT
 SET OPTION  ALWBLK = *ALLREAD ,
 ALWCPYDTA = *OPTIMIZE ,
 COMMIT = *ALL ,
 DBGVIEW = *SOURCE ,
 DECRESULT = (31, 31, 00) ,
 DFTRDBCOL = *NONE ,
 DYNDFTCOL = *NO ,
 DYNUSRPRF = *USER ,
 SRTSEQ = *HEX
 MAIN : BEGIN

--Variables fields
DECLARE SQLSTATE CHAR ( 5 ) ;
DECLARE RQCORRESPONDENCEID BIGINT ;
DECLARE SQLCODE INT ;
DECLARE C1 CURSOR FOR
SELECT
CORRESPONDENCE_ID FROM SESSION . REQUESTED ;



DECLARE GLOBAL TEMPORARY TABLE SESSION . REQUESTED
(
 CORRESPONDENCE_ID BIGINT
)
WITH REPLACE
;
DECLARE GLOBAL TEMPORARY TABLE SESSION . RESULTS
(
ID BIGINT ,
JOBID BIGINT ,
STATUS CHAR ( 10 ) ,
STATUS_CODE CHAR ( 10 ) ,
STATUS_TEXT CHAR ( 50 ) ,
CREATE_TS CHAR ( 26 )
)
WITH REPLACE
;

SET PRETCODE = '0000' ;
SET PRETDESC = 'populating temp table' ;



INSERT INTO SESSION . REQUESTED ( CORRESPONDENCE_ID )
SELECT * FROM JSON_TABLE ( PAYLOAD_IN , '$'
COLUMNS (
NESTED '$.DATA[*]' COLUMNS (
"correspondenceId" BIGINT )
)

) AS T ;

OPEN C1 ;
FETCH_LOOP :
LOOP

FETCH C1 INTO
RQCORRESPONDENCEID ;

IF SQLCODE <> 0 THEN
LEAVE FETCH_LOOP ;
END IF ;

INSERT INTO SESSION . RESULTS
(
ID ,
JOBID ,
STATUS ,
STATUS_CODE ,
STATUS_TEXT ,
CREATE_TS
)
SELECT
FAXSTATUS . ID , FAXSTATUS . JOBID , FAXSTATUS . FAX_STATUS , FAXSTATUS . STATUS_CODE ,
FAXSTATUS . STATUS_TEXT , CHAR ( FAXSTATUS . CREATE_TS )
FROM VPAYFAX . FSM_JOB_STATUS AS FAXSTATUS
INNER JOIN VPAYFAX . FSMJOB AS FAXJOB ON FAXSTATUS . JOBID = FAXJOB . ID
WHERE FAXJOB . CORRESP_ID = RQCORRESPONDENCEID ;

END LOOP FETCH_LOOP ;

-- send back results
SET PRETDESC = 'Populate payload_out' ;
SELECT JSON_OBJECT ( 'RESULTS' VALUE JSON_ARRAYAGG ( JSON_OBJECT (
'Id' VALUE ID ,
'JobId' VALUE JOBID ,
'Status' VALUE STATUS ,
'StatusCode' VALUE STATUS_CODE ,
'StatusText' VALUE STATUS_TEXT ,
'CreatedTime' VALUE CREATE_TS )
) FORMAT JSON )
INTO PAYLOAD_OUT
FROM SESSION . RESULTS ;

SET PRETDESC = 'Success' ;
END  ;


SET PATH *LIBL ;

CREATE PROCEDURE VPAYFAX.SP_PUT_FAX_JOB_ON_HOLD (
 INOUT PUSTOKEN CHAR(128) ,
 INOUT PRETCODE CHAR(4) ,
 INOUT PRETDESC CHAR(256) ,
 IN PJOBNUM INTEGER )
 LANGUAGE SQL
 SPECIFIC VPAYFAX.SPPFJH
 NOT DETERMINISTIC
 MODIFIES SQL DATA
 CALLED ON NULL INPUT
 SET OPTION  ALWBLK = *ALLREAD ,
 ALWCPYDTA = *OPTIMIZE ,
 COMMIT = *NONE ,
 DECRESULT = (31, 31, 00) ,
 DFTRDBCOL = *NONE ,
 DLYPRP = *NO ,
 DYNDFTCOL = *NO ,
 DYNUSRPRF = *USER ,
 SRTSEQ = *HEX
 MAIN : BEGIN
DECLARE TOKTRIM VARCHAR ( 128 ) ;
DECLARE USERID CHAR ( 20 ) ;
DECLARE REC_COUNT INTEGER ;
DECLARE BILC CHAR ( 20 ) ;
DECLARE CLIENT CHAR ( 10 ) ;
DECLARE OBJECT CHAR ( 512 ) ;
DECLARE ACTION CHAR ( 10 ) ;
DECLARE CORRESP_ID INTEGER ;
DECLARE QUEUE CHAR ( 10 ) ;
SET TOKTRIM = TRIM ( PUSTOKEN ) ,
USERID = '' ;
 SET CLIENT = 'NOTFOUND' ;
CALL VPAYSEC . SP_VERIFY_TOKEN ( TOKTRIM , USERID , PRETCODE , PRETDESC ) ;
IF PRETCODE = '0000' THEN
SELECT T . TMCLIC , T . TMBILC , F . QUEUE , F . CORRESP_ID INTO CLIENT , BILC
, QUEUE , CORRESP_ID
FROM FSMJOB F JOIN SEWCPS . CPSTMF T ON F . SE_TX_ID = T . TMTXID
WHERE ID = PJOBNUM
AND FAX_STATUS IN ( 'PENDING' , 'DUPENUMBER' , 'RETRY' )
;
IF QUEUE = 'FAXDISTRO' THEN
CALL VPAYPGM . SP_CHANGE_FAX_STATUS ( 'HOLD' , CORRESP_ID ) ;
ELSE
IF CLIENT = 'NOTFOUND' THEN
SET PRETCODE = '0001' ;
SET PRETDESC = 'Fax is not holdable currently' ;
ELSE
SET OBJECT = 'UNIVERSE
'
ACTION = 'DELETE' ;
CALL VPAYSEC . SP_CHECK_OBJECT_SECURITY (
USERID , OBJECT , ACTION , PRETCODE , PRETDESC ) ;
IF PRETCODE = '0000' THEN
UPDATE FSMJOB SET FAX_STATUS = 'HOLD'
WHERE ID = PJOBNUM
AND FAX_STATUS IN ( 'PENDING' , 'DUPENUMBER' , 'RETRY' )
;
SELECT COUNT ( * ) INTO REC_COUNT FROM FSMJOB
WHERE ID = PJOBNUM
AND FAX_STATUS = 'HOLD'
;
IF REC_COUNT = 0 THEN
SET PRETCODE = '0003' ,
PRETDESC = 'Fax ceased to be holdable' ;
ELSE
SET PRETDESC = 'Fax is on hold' ;
END IF ;
END IF ;
END IF ;
END IF ;
END IF ;
END  ;

