 SET OPTION  ALWBLK = *ALLREAD ,
 ALWCPYDTA = *OPTIMIZE ,
 COMMIT = *NONE ,
 DECRESULT = (31, 31, 00) ,
 DYNDFTCOL = *NO ,
 DYNUSRPRF = *USER ,
 SRTSEQ = *HEX
 BEGIN
 EXECUTE IMMEDIATE 'UPDATE       vpayfax.fsmjobSET       fax_status = ''RTEXC
EEDED'',       QUEUE = ''RTEXCEEDED'',       retrycount = 0,       last_statu
s_ts = current_timestampWHERE       se_tx_id IN(              SELECT
             DISTINCT setxid              FROM                     vpaybrddta.
nfpydt n              WHERE                     n.tpa = ''SWK''
       AND created_timestamp > CURRENT_DATE - 5 days                     AND se
nding_instructions = ''F''       )       AND se_tx_id NOT IN (SELECT DISTINCT
dmtxid FROM sewcps.cpscor WHERE dmcmth = ''RFAX'')       AND fax_status <> ''SE
NT''       AND reserve_name <> ''CSS''' ;
END  ;

