CREATE VIEW VPAYFAX.NEVER_SENT_FAILED_JOBS FOR SYSTEM NAME NEVER00001 (
 CLIC ,
 SE_TX_ID ,
 RECIEVER_NAME FOR COLUMN RECIE00001 ,
 FAX_NUMBER ,
 CREATE_DATE FOR COLUMN CREAT00001 ,
 CREATE_TIME FOR COLUMN CREAT00002 ,
 FINAL_DISPOSITION FOR COLUMN FINAL00001 ,
 UPDATE_DATE FOR COLUMN UPDAT00001 ,
 UPDATE_TIME FOR COLUMN UPDAT00002 )
 AS
 SELECT
  DMCLIC AS CLIC,
  DMTXID AS SE_TX_ID,
  DMRCVNM AS RECIVER_NAME,
  DMRCVFAX AS FAX_NUMBER,
  DMENDT AS CREATE_DATE,
  DMENTS AS CREATE_TIME,
  DMRMKS AS FINAL_DISPOSITION,
  DMUPDT AS UPDATE_DATE,
  DMUPTS AS UPDATE_TIME
  FROM
  VPAYFAX.FSMJOB F
  JOIN VPAYFAX.FSMJOB G ON (F.SE_TX_ID = G.SE_TX_ID AND F.ID != G.ID)
  JOIN SEWCPS.CPSCOR C ON (F.CORRESP_ID = C.DMRECID)
  WHERE
  F.CREATE_TS > '2010-09-08 00:00:00.000000'
  AND F.FAX_STATUS = 'RTEXCEEDED'
  AND G.FAX_STATUS <> 'SENT'
 RCDFMT NEVER00001 ;

LABEL ON TABLE VPAYFAX.NEVER_SENT_FAILED_JOBS
 IS 'Jobs that never have been successfully sent' ;

LABEL ON COLUMN VPAYFAX.NEVER_SENT_FAILED_JOBS
( CLIC IS 'Client              Code' ,
 SE_TX_ID IS 'Transaction ID' ,
 RECIEVER_NAME IS 'Recvr               Name' ,
 FAX_NUMBER IS 'Sender              Fax' ,
 CREATE_DATE IS 'Entered             Date' ,
 CREATE_TIME IS 'Entered             Time' ,
 FINAL_DISPOSITION IS 'REMARKS' ,
 UPDATE_DATE IS 'Update              Date' ,
 UPDATE_TIME IS 'Update              Time' ) ;

LABEL ON COLUMN VPAYFAX.NEVER_SENT_FAILED_JOBS
( CLIC TEXT IS 'Client Code' ,
 SE_TX_ID TEXT IS 'Transaction ID' ,
 RECIEVER_NAME TEXT IS 'Recvr Name' ,
 FAX_NUMBER TEXT IS 'Sender Fax' ,
 CREATE_DATE TEXT IS 'Entered Date' ,
 CREATE_TIME TEXT IS 'Entered Time' ,
 FINAL_DISPOSITION TEXT IS 'REMARKS' ,
 UPDATE_DATE TEXT IS 'Update Date' ,
 UPDATE_TIME TEXT IS 'Update Time' ) ;

GRANT ALTER , REFERENCES , SELECT
ON VPAYFAX.NEVER_SENT_FAILED_JOBS TO SE WITH GRANT OPTION ;

